"use server";

import { revalidatePath } from "next/cache";

import { prisma } from "@/lib/prisma";
import { type AdminResult, parseForm, runAction } from "@/lib/admin/form";
import { audit } from "@/lib/admin/audit";
import { requireAdminUser } from "@/lib/admin/guard";
import {
  discountGrantSchema,
  prescriptionSchema,
  purchaseSchema,
} from "@/lib/admin/schemas";

/**
 * Admin CRUD for the patient records that My Profile reads: prescriptions,
 * online purchases and discount grants.
 *
 * These are entered by staff rather than generated by the client's own
 * actions, so they live behind the admin console. Everything is audited —
 * they are the patient's record, and a change to one should be traceable.
 */

/** Blank date input means "now"; anything else is a YYYY-MM-DD day. */
function dateOrNow(value?: string): Date {
  if (!value) return new Date();
  const at = new Date(`${value}T00:00:00.000Z`);
  return Number.isNaN(at.getTime()) ? new Date() : at;
}

function dateOrNull(value?: string): Date | null {
  if (!value) return null;
  const at = new Date(`${value}T00:00:00.000Z`);
  return Number.isNaN(at.getTime()) ? null : at;
}

/** The patient's own page is cached per-path; a new record must show up. */
function revalidatePatient() {
  revalidatePath("/patient/profile");
}

/* ------------------------------ Prescriptions ---------------------------- */

export async function savePrescription(
  id: string | null,
  formData: FormData
): Promise<AdminResult> {
  return runAction("savePrescription", async () => {
    const user = await requireAdminUser();
    const parsed = parseForm(prescriptionSchema, formData);
    if (!parsed.ok) return parsed.result;

    const d = parsed.data;
    const data = {
      userId: d.userId,
      doctorId: d.doctorId || null,
      title: d.title,
      notes: d.notes || null,
      fileUrl: d.fileUrl,
      issuedAt: dateOrNow(d.issuedAt),
    };

    const before = id
      ? await prisma.prescription.findUnique({ where: { id } })
      : null;
    const row = id
      ? await prisma.prescription.update({ where: { id }, data })
      : await prisma.prescription.create({ data });

    await audit({
      userId: user.id,
      action: id ? "update" : "create",
      entity: "Prescription",
      entityId: row.id,
      before,
      after: row,
    });

    revalidatePatient();
    revalidatePath("/admin/prescriptions");
    return { ok: true, id: row.id };
  });
}

export async function deletePrescription(id: string): Promise<AdminResult> {
  return runAction("deletePrescription", async () => {
    const user = await requireAdminUser();
    const before = await prisma.prescription.findUnique({ where: { id } });
    await prisma.prescription.delete({ where: { id } });
    await audit({
      userId: user.id,
      action: "delete",
      entity: "Prescription",
      entityId: id,
      before,
    });
    revalidatePatient();
    revalidatePath("/admin/prescriptions");
    return { ok: true };
  });
}

