/* ----------------------------- Discount grants --------------------------- */

export async function saveDiscountGrant(
  id: string | null,
  formData: FormData
): Promise<AdminResult> {
  return runAction("saveDiscountGrant", async () => {
    const user = await requireAdminUser();
    const parsed = parseForm(discountGrantSchema, formData);
    if (!parsed.ok) return parsed.result;

    const d = parsed.data;
    const before = id
      ? await prisma.discountGrant.findUnique({ where: { id } })
      : null;

    // Ticking "used" stamps the redemption once and leaves the original
    // timestamp alone on later edits; unticking clears it.
    const usedAt = d.markUsed ? before?.usedAt ?? new Date() : null;

    const data = {
      userId: d.userId,
      code: d.code,
      description: d.description,
      percentOff: d.percentOff ?? null,
      amountOffInr: d.amountOffInr ?? null,
      expiresAt: dateOrNull(d.expiresAt),
      usedAt,
    };

    const row = id
      ? await prisma.discountGrant.update({ where: { id }, data })
      : await prisma.discountGrant.create({ data });

    await audit({
      userId: user.id,
      action: id ? "update" : "create",
      entity: "DiscountGrant",
      entityId: row.id,
      before,
      after: row,
    });

    revalidatePatient();
    revalidatePath("/admin/discounts");
    return { ok: true, id: row.id };
  });
}

export async function deleteDiscountGrant(id: string): Promise<AdminResult> {
  return runAction("deleteDiscountGrant", async () => {
    const user = await requireAdminUser();
    const before = await prisma.discountGrant.findUnique({ where: { id } });
    await prisma.discountGrant.delete({ where: { id } });
    await audit({
      userId: user.id,
      action: "delete",
      entity: "DiscountGrant",
      entityId: id,
      before,
    });
    revalidatePatient();
    revalidatePath("/admin/discounts");
    return { ok: true };
  });
}
